import re
lines=open('REGISTER-2_13.txt',encoding='utf-8').read().splitlines()
cur=None
first={}
counts={}
pats={'T §':r'T §','T locator (T n.n)':r'\bT \d+\.\d','violation index':r'violation index','companion':r'companion','Chinneck':r'Chinneck','Reeh':r'Reeh','Tomita':r'Tomita','Brunetti':r'Brunetti','6-cube':r'6-cube','null surface':r'null surface','NEC':r'\bNEC\b','audit 27':r'audit 27','split alphabet':r'split alphabet','V6':r'\bV6\b','charger':r'charger'}
for ln in lines:
    m=re.match(r'\s*(\d{1,4})[a-z]?\.\s',ln)
    if m: cur=int(m.group(1))
    for k,p in pats.items():
        if re.search(p,ln):
            counts[k]=counts.get(k,0)+1
            if k not in first: first[k]=cur
for k in pats:
    print(f"{k:22} first R {str(first.get(k,'-')):>6}   hits {counts.get(k,0)}")
EOF

